package jp.tapmarker;
import java.util.*;
public class RegionalLogicTest {
 static int checks=0;static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
 static void reject(String text,String label){try{PromptLogic.parse(text);throw new AssertionError(label);}catch(IllegalArgumentException e){check(true,label);}}
 public static void main(String[] args){PromptLogic.Plan p=PromptLogic.parse("監視領域が変わるまでマーカーを連打。遷移を記録。完了で停止。待機300ms");check(p.action==4&&p.record&&p.waitMs==300,"marker prompt maps to record and timing logic");p=PromptLogic.parse("描いた曲線をなぞる。変化したら学習した次の操作へ。変化しきい値0.01");check(p.action==5&&p.strict&&!p.record&&Math.abs(p.changeThreshold-.01)<1e-7,"curve prompt maps to observed transition execution");check(PromptLogic.parse("監視領域が変わるまで描いた曲線をなぞる。変化したら停止").stopOnChange,"explicit region-change stop parsed");reject("好きなゲームで勝って","unsupported instruction is rejected");reject("マーカーを連打。曲線をなぞる","contradictory operations rejected");reject("遷移を記録。記録済み遷移に従う","contradictory transition modes rejected");reject("待機3ms","invalid observation timing rejected");reject("変化しきい値0.2","invalid change threshold rejected");reject("","empty prompt rejected");float[] roi={.25f,.25f,.75f,.75f};int[] bounds=RegionMath.bounds(roi,100,200);check(Arrays.equals(bounds,new int[]{25,50,75,150}),"normalized region maps to screen rectangle");final int[] calls={0};float[] a=RegionSampler.sample(100,200,roi,(x,y)->{if(x<25||x>=75||y<50||y>=150)throw new AssertionError("outside ROI");calls[0]++;return 0xff112233;});check(calls[0]==2304,"all pixel reads stay inside monitor region");float[] b=RegionSampler.sample(100,200,roi,(x,y)->x>=25&&x<75&&y>=50&&y<150?0xff112233:0xffffffff);check(FlyCircuit.distance(a,b)==0,"outside-region changes do not affect features");float[] c=RegionSampler.sample(100,200,roi,(x,y)->0xff223344);check(FlyCircuit.distance(a,c)>0,"inside-region changes affect features");check(CurveMath.length(new float[]{0,0,100,0,100,100,0,0})>24,"closed curve retains gesture despite matching endpoints");check(CurveMath.length(new float[]{10,10,11,11})<24,"tiny trace is treated as tap");ArrayList<Float> trace=new ArrayList<>();for(int i=0;i<5000;i++)CurveMath.append(trace,i,(float)Math.sin(i*.01));check(trace.size()<=512,"long curves are resampled without unbounded memory");check(trace.get(0)==0&&trace.get(trace.size()-2)==4999,"curve resampling keeps beginning and latest endpoint");TransitionMemory m=new TransitionMemory();check(!m.permits("appA:roiA","stateA","stateB"),"unseen transition blocked");m.observe("appA:roiA","stateA","stateB");check(m.permits("appA:roiA","stateA","stateB"),"observed directed transition permitted");check(!m.permits("appA:roiA","stateB","stateA"),"reverse direction not invented");check(!m.permits("appB:roiA","stateA","stateB"),"another app cannot inherit transition");check(!m.permits("appA:roiB","stateA","stateB"),"another monitor region cannot inherit transition");m.observe("appA:roiA","stateA","stateA");check(m.counts.size()==1,"same-state observation not recorded as transition");ArrayList<ScreenPolicy.Example> examples=new ArrayList<>();ScreenPolicy.Example old=new ScreenPolicy.Example();old.pkg="appA";old.width=100;old.height=200;old.raw=a;old.embedding=new float[]{0};examples.add(old);check(ScreenPolicy.select(examples,"appA",100,200,a,new float[]{0},RegionMath.key(roi))==-1,"full-screen legacy learning cannot match regional learning");old.regionKey=RegionMath.key(roi);check(ScreenPolicy.select(examples,"appA",100,200,a,new float[]{0},RegionMath.key(roi))==0,"matching region learning selected");System.out.println("TOTAL "+checks+" regional logic checks passed; device gestures not tested.");}
}
